-- Coriolanus
DELETE FROM projectTags WHERE projectId = (SELECT id FROM projects WHERE slug = 'coriolanus');
INSERT INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p CROSS JOIN tags t
WHERE p.slug = 'coriolanus'
AND t.name IN ('Shakespeare', 'Minimalist', 'Unit Set', 'Theatre Festival', '2022', 'Tragedy');

